import sys

data = sys.stdin.read().split()
n, target = int(data[0]), int(data[1])
nums = [int(x) for x in data[2:2 + n]]
cnt = 0
for mask in range(1 << n):
    s = 0
    for i in range(n):
        if mask >> i & 1:
            s += nums[i]
    if s == target:
        cnt += 1
print(cnt % (10**9 + 7))

